questionvariables.text:
/* Linear scale factor p/q in lowest terms, p > q */
qden : rand(4) + 2;
pnum : qden + rand(4) + 1;
g : gcd(pnum, qden);
pnum : pnum / g;
qden : qden / g;

/* Base multiplier so both areas come out as whole numbers */
m : rand(5) + 2;
area_small : m * qden^2;
area_large : m * pnum^2;

/* Correct answer: linear scale factor from the smaller to the larger triangle */
ta : decimalplaces(pnum/qden, 2);

/* mistakes */
/* Forgot to take the square root, used the area ratio directly */
ta1 : decimalplaces(area_large/area_small, 2);
/* Found the scale factor the wrong way round (large to small) */
ta2 : decimalplaces(qden/pnum, 2);
